function startTimer(){clearInterval(S.qi);const t=LV[lvl()].t;if(!t)return;S.left=t;S.qi=setInterval(()=>{S.left-=.25;const b=document.getElementById("qtb");if(b)b.style.width=Math.max(0,S.left/t*100)+"%";if(S.left<=0){clearInterval(S.qi);pick(-1)}},250)}
