const DESK_CATS=[{"n": "Software Problems", "d": "Apps that crash, freeze or won't open", "i": "🧩", "c": "#22d3ee"}, {"n": "Internet Problems", "d": "No Wi-Fi, weak signal, can't connect", "i": "🌐", "c": "#a78bfa"}, {"n": "Slow Computer Problems", "d": "Lag, full drive, slow start-up", "i": "🐢", "c": "#facc15"}, {"n": "Windows (OS) Problems", "d": "Blue screens and PCs that won't start", "i": "💿", "c": "#f472b6"}, {"n": "Device Problems", "d": "Mouse, keyboard & more", "i": "⌨️", "c": "#34d399"}];
const DESK_LIST=[{"n": "No internet", "c": 1, "t": "A student says: \"I can't open any website.\""}, {"n": "Frozen app", "c": 0, "t": "Notes froze and the whole computer is slow."}, {"n": "Slow start-up", "c": 2, "t": "A teacher says the computer takes minutes to start and is slow all day."}, {"n": "Pop-up ads", "c": 0, "t": "Ads keep popping up in the browser."}, {"n": "Too many tabs", "c": 2, "t": "A browser with lots of tabs is very slow."}, {"n": "Power saver mode", "c": 2, "t": "A new laptop is slow, even for simple things."}, {"n": "Printer offline", "c": 4, "t": "The printer shows Offline and nothing prints."}, {"n": "Hidden program", "c": 2, "t": "The PC is slow and a strange app is using a lot of power."}, {"n": "Wrong Wi-Fi password", "c": 1, "t": "A laptop says \"Can't connect to this network\"."}, {"n": "Router stuck", "c": 1, "t": "Nobody in the room can get online."}, {"n": "No network address", "c": 1, "t": "The PC says \"Limited connection\" and has no network address."}, {"n": "Websites not loading", "c": 1, "t": "Wi-Fi says connected, but websites will not open."}, {"n": "Forgot PIN", "c": 3, "t": "A student forgot the PIN and can't sign in."}, {"n": "Update failed", "c": 3, "t": "Windows Update stops and shows an error."}, {"n": "Broken Windows files", "c": 3, "t": "Windows shows random errors and some apps crash."}, {"n": "Crash after part update", "c": 3, "t": "A blue screen appears after a PC part helper program (driver) was installed."}, {"n": "PC won't start", "c": 3, "t": "The PC shows a blue screen and keeps restarting."}, {"n": "App won't open", "c": 0, "t": "A student double-clicks an app but nothing opens."}, {"n": "Problem after update", "c": 0, "t": "The printer app crashes right after an update."}, {"n": "Missing file error", "c": 0, "t": "A student opens Photo Editor and it says a file is missing."}, {"n": "Hot and dusty PC", "c": 2, "t": "The PC is hot, loud and slows down after 10 minutes."}, {"n": "No signal on monitor", "c": 4, "t": "The monitor says \"No signal\"."}, {"n": "Mouse and keyboard", "c": 4, "t": "The mouse does not move and the keyboard types the wrong letters."}, {"n": "Stuck print queue", "c": 4, "t": "One document will not print and blocks all the others."}, {"n": "USB not detected", "c": 4, "t": "A flash drive does not show in Files."}];   // same 25 problems, same order, as the Desktop simulator
const DK=()=>{SIM.desk=SIM.desk||{};SIM.desk.d=SIM.desk.d||{};return SIM.desk.d};
const simPts=()=>Object.values(DK()).reduce((a,v)=>a+(v.s||0),0),simN=()=>Object.keys(DK()).length;
const deskQ=()=>Object.values(DK()).reduce((a,v)=>[a[0]+(v.q||0),a[1]+(v.qn||0)],[0,0]);
function deskCanPlay(){if(!P)return false;if(STUDY_MODE&&!(P.tests&&P.tests.pre)){alert("Take the Pre-Test first.");return false}return true}
function deskSeed(){const o={};Object.entries(DK()).forEach(([k,v])=>{o[k]=v.s||0});return o}
function deskSave(){try{localStorage.setItem(pk()+":sim",JSON.stringify(SIM))}catch(e){}save()}
function deskRec(i,r){simLoadK();const d=DK(),o=d[i]||{},n=Object.assign({},o);
 n.s=Math.max(o.s||0,r.score);n.st=Math.max(o.st||0,r.stars);n.last=r.score;n.tries=(o.tries||0)+1;n.at=new Date().toISOString();
 if(!o.f)n.f={s:r.score,w:r.wasted,h:r.hints,t:r.secs};   // FIRST attempt is kept for the research record
 d[i]=n;deskSave()}
function deskQuiz(i,right,qn){simLoadK();const d=DK(),o=d[i]||{};if(!o.qf)o.qf=[right,qn];o.q=Math.max(o.q||0,right);o.qn=qn;d[i]=o;deskSave()}
function simGet(){return JSON.parse(JSON.stringify(SIM))}
