app.innerHTML=`<div class="hud"><button class="hb" onclick="home()">← Back</button><span class="hp">📚 Learn</span></div><div class="card lg" style="margin-top:14px;text-align:left"><label>🔎 Search a problem or a word<input id="lq" placeholder="printer, wifi, slow, blue screen…" autocomplete="off" value="${esc(LQ)}"></label><div id="lch" style="display:flex;flex-wrap:wrap;gap:6px;margin:8px 0"></div></div><div id="lres"></div>`;
