function svDomM(a){return[0,1,2].map(d=>avg(a.slice(d*5,d*5+5)))}
function avg(a){return a.reduce((x,y)=>x+y,0)/a.length}
function sdv(a){if(a.length<2)return 0;const m=avg(a);return Math.sqrt(a.reduce((s,v)=>s+(v-m)*(v-m),0)/(a.length-1))}
function svCols(){const a=P&&P.survey?P.survey.a:null,o={};SVC.forEach((c,i)=>o[c]=a?a[i]:"");const m=a?svDomM(a):["","",""];o["Survey UI mean"]=a?+m[0].toFixed(2):"";o["Survey Ease of Use mean"]=a?+m[1].toFixed(2):"";o["Survey Functionality mean"]=a?+m[2].toFixed(2):"";o["Consent"]=P&&P.consent?"Yes":"";return o}

