function lgam(x){const c=[76.18009172947146,-86.50532032941677,24.01409824083091,-1.231739572450155,0.1208650973866179e-2,-0.5395239384953e-5];let y=x,t=x+5.5,s=1.000000000190015;t-=(x+.5)*Math.log(t);for(let j=0;j<6;j++)s+=c[j]/++y;return -t+Math.log(2.5066282746310005*s/x)}
function bcf(a,b,x){const T=1e-30,qab=a+b,qap=a+1,qam=a-1;let c=1,d=1-qab*x/qap,h,aa,del;if(Math.abs(d)<T)d=T;d=1/d;h=d;for(let m=1;m<=300;m++){const m2=2*m;aa=m*(b-m)*x/((qam+m2)*(a+m2));d=1+aa*d;if(Math.abs(d)<T)d=T;c=1+aa/c;if(Math.abs(c)<T)c=T;d=1/d;h*=d*c;aa=-(a+m)*(qab+m)*x/((a+m2)*(qap+m2));d=1+aa*d;if(Math.abs(d)<T)d=T;c=1+aa/c;if(Math.abs(c)<T)c=T;d=1/d;del=d*c;h*=del;if(Math.abs(del-1)<3e-14)break}return h}
function ibeta(x,a,b){if(x<=0)return 0;if(x>=1)return 1;const bt=Math.exp(lgam(a+b)-lgam(a)-lgam(b)+a*Math.log(x)+b*Math.log(1-x));return x<(a+1)/(a+b+2)?bt*bcf(a,b,x)/a:1-bt*bcf(b,a,1-x)/b}
function tP2(t,df){return ibeta(df/(df+t*t),df/2,.5)}
function tCrit(df){let lo=0,hi=200;for(let i=0;i<100;i++){const m=(lo+hi)/2;if(tP2(m,df)>.05)lo=m;else hi=m}return(lo+hi)/2}
function pairedT(pre,post){const n=pre.length;if(n<2)return null;const d=post.map((v,i)=>v-pre[i]),md=avg(d),sd=sdv(d),se=sd/Math.sqrt(n),tc=tCrit(n-1);let t,p;if(sd===0){t=md===0?0:(md>0?Infinity:-Infinity);p=md===0?1:0}else{t=md/se;p=tP2(t,n-1)}return{n,df:n-1,m1:avg(pre),m2:avg(post),s1:sdv(pre),s2:sdv(post),md,sd,se,t,p,tc,lo:md-tc*se,hi:md+tc*se,dz:sd?md/sd:(md?Infinity:0)}}
const f2=x=>Number.isFinite(x)?x.toFixed(2):String(x),pf=p=>p<.001?"< .001":"= "+p.toFixed(3).replace(/^0/,"");
const dzW=d=>{d=Math.abs(d);return d<.2?"negligible":d<.5?"small":d<.8?"medium":"large"};
let RS={rows:[],src:"",ok:false,smp:false};
const rsKey=r=>(r.email||r.id||(r.name+"|"+r.sec)).toLowerCase();
function mkRow(name,sec,id,email,pre,post,sv,x){x=x||{};return{name:name||"",sec:sec||"",id:id||"",email:email||"",pre:pre&&pre.s!=null?+pre.s:null,preN:pre&&pre.n!=null?+pre.n:null,post:post&&post.s!=null?+post.s:null,postN:post&&post.n!=null?+post.n:null,sv:sv&&sv.a&&sv.a.length==15?sv.a.map(Number):null,pa:x.pa||null,qa:x.qa||null,con:!!x.con}}
function rsDs(r,sim){const v=Object.values((sim&&sim.desk&&sim.desk.d)||{});r.dn=v.length;r.dp=v.reduce((a,x)=>a+(x.s||0),0);r.qr=v.reduce((a,x)=>a+(x.q||0),0);r.qn=v.reduce((a,x)=>a+(x.qn||0),0);return r}
function rsDedupe(rows){const m={};rows.forEach(r=>{const k=rsKey(r),o=m[k];if(!o)m[k]=r;else Object.keys(r).forEach(f=>{if(r[f]!==null&&r[f]!==""&&(o[f]===null||o[f]===""))o[f]=r[f]})});return Object.keys(m).map(k=>m[k])}
