  pool.addEventListener("click",e=>{const c=e.target.closest(".pc");if(dead(c))return;if(c._d){c._d=0;return}const same=S.sel==c.dataset.k;pool.querySelectorAll(".sel").forEach(x=>x.classList.remove("sel"));S.sel=null;if(!same){S.sel=+c.dataset.k;c.classList.add("sel");beep(520,.05)}});
